// Parsear mensaje de Brian
const message = $input.first().json.message;
const text = (message.text || '').toLowerCase().trim();
const chatId = message.chat.id;

// Palabras clave por tipo de notificación
const SALIDA_KEYS = ['salida', 'salio', 'salió', 'sale', 'partio', 'partió'];
const CRUCE_KEYS = ['cruce', 'cruzo', 'cruzó', 'libero', 'liberó', 'liberado', 'liberada', 'frontera'];
const ARRIBO_KEYS = ['arribo', 'arribó', 'fiscal', 'llego', 'llegó'];

// Extraer referencia (4 dígitos)
const refMatch = text.match(/\b[aA]?(\d{4})\b/);
const ref = refMatch ? refMatch[1] : null;

// Detectar tipo
let tipo = null;
if (SALIDA_KEYS.some(k => text.includes(k))) tipo = 'salida';
else if (CRUCE_KEYS.some(k => text.includes(k))) tipo = 'cruce';
else if (ARRIBO_KEYS.some(k => text.includes(k))) tipo = 'arribo';

// Extraer fecha ("miercoles 25", "lunes 28/03", "25/03", etc.)
const dias = ['lunes','martes','miercoles','miércoles','jueves','viernes','sabado','sábado','domingo'];
let fecha = null;
let fechaTexto = null;

// Patrón: día de la semana + número
const diaMatch = text.match(new RegExp(`(${dias.join('|')})\\s*(\\d{1,2})(?:[/\\-](\\d{1,2}))?`));
if (diaMatch) {
  const dia = diaMatch[1].charAt(0).toUpperCase() + diaMatch[1].slice(1).replace('é','e').replace('á','a');
  const num = diaMatch[2];
  const mes = diaMatch[3] || new Date().toLocaleDateString('es-AR', {month:'2-digit'}).replace(/^0/,'');
  fecha = `${num}/${mes.padStart(2,'0')}`;
  fechaTexto = `${dia} ${fecha}`;
}

// Patrón: solo número/mes
if (!fecha) {
  const numMatch = text.match(/(\d{1,2})[/\-](\d{1,2})/);
  if (numMatch) {
    fecha = `${numMatch[1]}/${numMatch[2].padStart(2,'0')}`;
    fechaTexto = fecha;
  }
}

// Extraer contenedor (4 letras + 7 números)
const cntrMatch = text.match(/[A-Za-z]{4}\d{7}/);
const contenedor = cntrMatch ? cntrMatch[0].toUpperCase() : null;

return [{
  json: {
    chatId,
    ref,
    tipo,
    fecha,
    fechaTexto,
    contenedor,
    textoOriginal: message.text,
    esValido: !!(ref && tipo)
  }
}];

// Componer email de notificación
const parsed = $('Parsear Mensaje').first().json;
const thread = $input.first().json;

// Determinar saludo según hora
const hora = new Date().getHours();
const saludos_dia = [
  'Buenos días,',
  'Estimados, buenos días,',
  'Buenas,'
];
const saludos_tarde = [
  'Buenas tardes,',
  'Estimados, buenas tardes,',
  'Buenas,',
  'Hola, buenas tardes,'
];
const saludos = hora < 12 ? saludos_dia : saludos_tarde;
const saludo = saludos[Math.floor(Math.random() * saludos.length)];

// Cierres variados
const cierres = ['Saludos cordiales,', 'Quedamos a disposición,', 'Saludos,'];
const cierre = cierres[Math.floor(Math.random() * cierres.length)];

// Templates por tipo
let mensaje = '';
switch(parsed.tipo) {
  case 'salida':
    mensaje = 'Les informamos que la unidad ha salido rumbo a frontera. Los mantenemos informados sobre la liberación.';
    break;
  case 'cruce':
    if (parsed.fechaTexto) {
      mensaje = `Les informamos que la unidad ha sido liberada de frontera. Se presenta el ${parsed.fechaTexto} en destino.`;
    } else {
      mensaje = 'Les informamos que la unidad ha sido liberada de frontera.';
    }
    break;
  case 'arribo':
    mensaje = 'Les confirmamos que la unidad ya se encuentra en fiscal. Quedamos a la espera de la liberación para coordinar la descarga.';
    break;
}

// HTML del email
const htmlBody = `<div style="font-family:Arial,sans-serif;color:#333;max-width:600px;">
  <p style="font-size:14px;line-height:1.6;">${saludo}</p>
  <p style="font-size:14px;line-height:1.6;">${mensaje}</p>
  <p style="font-size:14px;line-height:1.6;margin:16px 0 0;">${cierre}</p>
  <div style="margin-top:24px;border-top:2px solid #e8762b;padding-top:16px;">
    <img src="https://twfnew-c7v2.vercel.app/images/FIRMA.png" alt="Brian Ridvanovich - TWF General Manager" width="500" style="width:500px;max-width:100%;height:auto;" />
  </div>
</div>`;

// Datos del thread para el draft
const lastMessage = thread.messages ? thread.messages[thread.messages.length - 1] : thread;
const subject = lastMessage.subject || thread.subject || `OP ${parsed.ref}`;
const to = lastMessage.to || thread.to || '';

// Tipo display
const tipoDisplay = {
  'salida': 'Salida desde Uruguay',
  'cruce': 'Cruce de frontera',
  'arribo': 'Arribo a fiscal'
};

return [{
  json: {
    threadId: thread.threadId || thread.id,
    subject: subject.startsWith('Re:') ? subject : `Re: ${subject}`,
    to,
    htmlBody,
    tipoDisplay: tipoDisplay[parsed.tipo],
    ref: parsed.ref,
    chatId: parsed.chatId
  }
}];
